const menuItems = $('Get Active Menu Items').all().map(i => i.json);
const body = $('Webhook: New Quote Request').first().json.body;

function normalise(s) {
  return String(s).toLowerCase().trim().replace(/[^a-z0-9 ]/g, '');
}

// Cheap fuzzy match: normalised exact match first, then token-overlap ratio.
function bestMatch(rawName) {
  const target = normalise(rawName);
  let best = null;
  let bestScore = 0;
  for (const item of menuItems) {
    const candidate = normalise(item.name);
    if (candidate === target) return { item, score: 1 };
    const targetTokens = new Set(target.split(' '));
    const candTokens = new Set(candidate.split(' '));
    const overlap = [...targetTokens].filter(t => candTokens.has(t)).length;
    const score = overlap / Math.max(targetTokens.size, candTokens.size);
    if (score > bestScore) { bestScore = score; best = item; }
  }
  return bestScore >= 0.6 ? { item: best, score: bestScore } : null;
}

const results = (body.items || []).map(orderedItem => {
  const match = bestMatch(orderedItem.name);
  if (match) {
    return {
      item_name_raw: orderedItem.name,
      quantity: orderedItem.quantity,
      is_custom: false,
      menu_item_id: match.item.id,
      unit_price: Number(match.item.unit_price)
    };
  }
  return {
    item_name_raw: orderedItem.name,
    quantity: orderedItem.quantity,
    is_custom: true,
    menu_item_id: null,
    unit_price: null
  };
});

return [{ json: { customer: body.customer, event: body.event, items: results } }];

const data = $input.first().json;
const customItems = data.items.filter(i => i.is_custom);

for (const item of customItems) {
  const prompt = `Estimate a fair, realistic ZAR price for ONE unit of this catering menu item, based on typical Cape Town, South Africa takeaway/catering prices in 2026: "${item.item_name_raw}". Reply ONLY as JSON: {"price": number, "confidence": "low"|"medium"|"high", "reason": "one short sentence"}`;

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 200,
      messages: [{ role: 'user', content: prompt }]
    },
    json: true
  });

  let parsed;
  try {
    const text = response.content.map(b => b.text || '').join('');
    parsed = JSON.parse(text.replace(/```json|```/g, '').trim());
  } catch (e) {
    parsed = { price: null, confidence: 'low', reason: 'AI estimate failed - manager must price manually' };
  }

  item.ai_estimated_price = parsed.price;
  item.ai_estimate_confidence = parsed.confidence;
  item.ai_estimate_source = parsed.reason;
  // The order still needs a number to show the customer, so use the
  // estimate as a clearly-marked placeholder unit price.
  item.unit_price = parsed.price;
}

return [{ json: data }];

const data = $('AI Estimate Cape Town Price (custom items)').first().json;
const customerId = $('Upsert Customer').first().json.id;

const items = data.items.map(i => ({
  ...i,
  line_total: (i.unit_price || 0) * i.quantity,
  price_status: i.is_custom ? 'estimated_placeholder' : 'confirmed'
}));

const grandTotal = items.reduce((sum, i) => sum + i.line_total, 0);
const containsEstimate = items.some(i => i.is_custom);
const quoteNumber = 'RES-' + new Date().getFullYear().toString().slice(-2) + '-' + Math.floor(1000 + Math.random() * 9000);

return [{ json: { customerId, quoteNumber, items, grandTotal, containsEstimate, event: data.event, customer: data.customer } }];

